/**
 * bodge-readme-writer — generates the README.md placed at the root of
 * every .bodge ZIP for archive longevity + sharing without BodgeGene.
 *
 * Spec §2.3:
 *   - Plain markdown, zero JS, zero attack surface.
 *   - Auto-generated on every write — derived artifact, NOT source of truth.
 *   - Does NOT contain sha256 / deviceId / raw notebook text — quick
 *     overview only, not audit log.
 *
 * Inputs are the plain-JS data the writer already has at hand; no need
 * to re-read containers / assemblies.
 */

const SECTION_BREAK = '\n\n';

/**
 * Build the README.md content for a v2 .bodge ZIP.
 *
 * @param {object} args
 * @param {object} args.manifest  — full v2 manifest (uses metadata + refs).
 * @param {object} args.projectMeta — project name / dates / tags / description.
 * @param {Map<string, object>} args.assembliesMap — id → parsed assembly (for fragment count).
 * @param {object[]} args.containers — parsed container records (for length/topology display).
 * @param {object} args.primerPool — `{primers: [...]}` shape.
 * @param {object[]} args.notebookEntries — for entry count + attachment count.
 * @returns {string} README.md content.
 */
export function buildReadme({
  manifest,
  projectMeta = {},
  assembliesMap = new Map(),
  containers = [],
  primerPool = null,
  notebookEntries = [],
  attachmentsManifest = {},
} = {}) {
  if (!manifest) throw new Error('buildReadme: manifest required');
  const lines = [];

  const title = manifest.metadata?.title || projectMeta.name || 'BodgeGene project';
  lines.push(`# ${title}`);
  lines.push('');

  const createdAt = formatDate(manifest.metadata?.createdAt);
  const updatedAt = formatDate(manifest.metadata?.updatedAt);
  const author = manifest.metadata?.author?.name || projectMeta.author || 'unknown';
  const appVersion = manifest.appVersion || 'unknown';
  const fileFormat = manifest.fileFormatVersion || 'unknown';
  lines.push(
    `**BodgeGene project** | Created: ${createdAt} | Updated: ${updatedAt}`,
  );
  lines.push(`Author: ${author} | BodgeGene v${appVersion} | File format: ${fileFormat}`);
  lines.push('');

  // Description (optional).
  const description = manifest.metadata?.description || projectMeta.description || '';
  if (description) {
    lines.push('## Описание');
    lines.push('');
    lines.push(description);
    lines.push('');
  }
  if (Array.isArray(manifest.metadata?.tags) && manifest.metadata.tags.length) {
    lines.push(`Tags: ${manifest.metadata.tags.join(', ')}`);
    lines.push('');
  }

  // Structure overview.
  lines.push('## Структура');
  lines.push('');
  lines.push(buildContainersSection(containers));
  lines.push('');
  lines.push(buildAssembliesSection(assembliesMap));
  lines.push('');
  lines.push(buildPrimersSection(primerPool));
  lines.push('');
  lines.push(buildNotebookSection(notebookEntries, attachmentsManifest));
  lines.push('');
  lines.push(buildLibrarySection(manifest));
  lines.push('');

  // How to open.
  lines.push('## Как открыть');
  lines.push('');
  lines.push(`- **\`.bodge\` archive (canonical):** BodgeGene v${appVersion}+`);
  lines.push('- **Individual `.gb` files:** SnapGene, ApE, Geneious Prime, любой GenBank viewer');
  lines.push('- **`README.md` (этот файл):** любой markdown viewer / просто текстовый редактор');
  lines.push('- **Notebook attachments (`.png`, `.ab1`):** стандартные tools');
  lines.push('');

  // Format documentation.
  lines.push('## Format documentation');
  lines.push('');
  lines.push('https://bodgegene.dev/format/v2');
  lines.push('');

  // README is auto-generated marker.
  lines.push('---');
  lines.push('');
  lines.push('_README.md auto-generated by BodgeGene at save-time. Hand edits are lost on next save._');
  lines.push('');

  return lines.join('\n');
}

function buildContainersSection(containers) {
  if (!containers.length) return '### Containers (0)\n\n(empty)';
  const out = [`### Containers (${containers.length})`, ''];
  for (const c of containers) {
    const len = c.sequence ? `${c.sequence.length} bp` : '? bp';
    const topo = c.topology || 'linear';
    const path = `containers/${c.id}.gb`;
    out.push(`- \`${path}\` — **${c.name || c.id}**, ${len} ${topo}`);
  }
  return out.join('\n');
}

function buildAssembliesSection(assembliesMap) {
  const list = Array.from(assembliesMap.values?.() || []);
  if (!list.length) return '### Assemblies (0)\n\n(empty)';
  const out = [`### Assemblies (${list.length})`, ''];
  for (const a of list) {
    const fragmentCount = Array.isArray(a.pieces) ? a.pieces.length : 0;
    const opKinds = Array.isArray(a.operations)
      ? Array.from(new Set(a.operations.map(o => o.kind))).join(', ')
      : '';
    const path = `assemblies/${a.id}.json`;
    const method = opKinds || 'draft';
    out.push(`- \`${path}\` — **${a.name || a.id}** (${fragmentCount} fragments, ${method})`);
  }
  return out.join('\n');
}

function buildPrimersSection(primerPool) {
  const primers = primerPool?.primers || [];
  const count = primers.filter(p => p?.kind !== 'pair').length;
  if (!count) return '### Primers\n\n(empty)';
  return `### Primers\n\n- \`primers/pool.json\` — ${count} primers (project-scoped)`;
}

function buildNotebookSection(entries, attachmentsManifest) {
  const entryCount = Array.isArray(entries) ? entries.length : 0;
  const attachmentCount = attachmentsManifest && typeof attachmentsManifest === 'object'
    ? Object.keys(attachmentsManifest).length
    : 0;
  if (!entryCount && !attachmentCount) {
    return '### Lab journal\n\n(empty — added in NOTEBOOK sprint)';
  }
  const out = ['### Lab journal', ''];
  if (entryCount) out.push(`- \`notebook/entries.json\` — ${entryCount} entries`);
  if (attachmentCount) out.push(`- \`notebook/attachments/\` — ${attachmentCount} files`);
  return out.join('\n');
}

function buildLibrarySection(manifest) {
  if (!manifest.refs?.library) return '### Library index\n\n(empty)';
  return '### Library index\n\n- `library/entries.json` — project library entries';
}

function formatDate(iso) {
  if (!iso) return 'unknown';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toISOString().slice(0, 10);
}

/**
 * Light sanity check — README.md must NOT contain sensitive fields.
 * Used by K16 test #5 and by K10 public-supp profile guard.
 */
export function validateReadmeSafe(readme) {
  const errors = [];
  if (!readme || typeof readme !== 'string') return { ok: false, errors: ['empty README'] };
  if (/sha256[:\s]*[a-f0-9]{64}/i.test(readme)) errors.push('README contains sha256 hash');
  if (/\b[a-f0-9]{64}\b/i.test(readme)) errors.push('README contains 64-char hex (likely sha256)');
  if (/deviceId\s*[:=]/i.test(readme)) errors.push('README contains deviceId');
  // Lenient on names that look like emails — only flag the deviceId/UUID
  // patterns which are clear telemetry leaks.
  if (/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i.test(readme)) {
    errors.push('README contains UUID — possible deviceId leak');
  }
  return { ok: errors.length === 0, errors };
}

export { SECTION_BREAK as _SECTION_BREAK };
